<script setup lang="ts">
import { t as uiText } from '@/locales'
import { computed,onBeforeUnmount,reactive,ref,watch } from 'vue'
import { ElMessage,ElMessageBox } from 'element-plus'
import { useRouter } from 'vue-router'
import { useWindowSize } from '@vueuse/core'
import { useUserStore } from '@/stores/user'
import { useCollaborationWorkspace } from '@/stores/collaborationWorkspace'
import * as api from '@/api/modules/moldApplications'
import SharedCompatiblePhoneSelector from '@/views/mold/components/SharedCompatiblePhoneSelector.vue'
import type { CompatiblePhone } from '@/types/molds'
import { phoneMemberName } from '@/utils/phoneMembers'
import { moldHandlerName } from '@/utils/moldApplicationHandlers'
import MoldApplicationFile from './MoldApplicationFile.vue'
import '../application-drawer.scss'
const props=defineProps<{options?:api.MoldOptions;projectId?:number|null;researchHost?:boolean}>()
const emit=defineEmits<{changed:[row:api.MoldApplication];deleted:[id:number];edit:[row:api.MoldApplication];'other-phone':[projectId:number];error:[message:string]}>()
const user=useUserStore(),workspace=useCollaborationWorkspace(),router=useRouter(),{width:viewportWidth}=useWindowSize()
const localOptions=ref<api.MoldOptions>(),options=computed(()=>props.options||localOptions.value)
const detail=ref<api.MoldApplication>(),drawer=ref(false),loading=ref(false),busy=ref(false),error=ref(''),deletingId=ref<number|null>(null)
let detailEpoch=0
const selectedId=ref<number>(),expectedProject=ref<number>()
const hasHistoricalAssociation=(r:api.MoldApplication)=>!!r.historicalAssociation?.associationOnly
const label=(r:api.MoldApplication)=>api.moldBusinessStatusNames[r.businessStatus||'approval_unknown']
const currentPhoneName=(row:api.MoldApplication)=>row.standardPhone?phoneMemberName(row.standardPhone):row.model||'未填写型号'
const currentPhoneCode=(row:api.MoldApplication)=>row.standardPhone?row.standardPhone.phoneModelCode||'待分配':row.phoneModelCode||'待核对'
const researchProjectId=(row:api.MoldApplication)=>row.sourceSnapshot?.research?.projectId||(props.researchHost?expectedProject.value||props.projectId||undefined:undefined)
const controls=computed(()=>options.value?.controls.filter(c=>!['DDPhotoField','DDAttachment'].includes(c.type)&&!['generatedCodes','informationComplete'].includes(c.key))||[])
const statusNames:Record<string,string>={draft:'草稿',submitting:'提交中',submission_unknown:'提交待核对',submitted:'审批中',withdrawing:'撤回中',withdrawal_unknown:'撤回待核对',terminated:'已终止',completed:'流程已结束',converted:'已转项目',RUNNING:'运行中',COMPLETED:'流程已结束',TERMINATED:'已终止'}
function chinaTime(value:string|null|undefined,dateOnly=false){if(!value)return '';const d=new Date(value);if(Number.isNaN(d.getTime()))return value;return new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',...(dateOnly?{}:{hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false})}).format(d)}
function sourceRecords(row?:api.MoldApplication):Record<string,unknown>[] {const sources=row?.sourceSnapshot?.sources;return Array.isArray(sources)?sources as Record<string,unknown>[]:[]}
function sourceUrl(source:Record<string,unknown>){const raw=source.source_url||source.sourceUrl;try{const value=new URL(String(raw||''));return ['http:','https:'].includes(value.protocol)?value.href:undefined}catch{return undefined}}
function current(epoch:number,auth:string){return drawer.value&&epoch===detailEpoch&&auth===user.token}
function close(){++detailEpoch;++historyEpoch;drawer.value=false;detail.value=undefined;loading.value=false;busy.value=false;error.value='';historyOpen.value=false;targetCorrectionOpen.value=false;historyPreview.value=undefined;historyError.value='';historyBusy.value=false;deletingId.value=null}
async function open(id:number,context:{projectId?:number;initial?:api.MoldApplication;reviewHistorical?:boolean}={}){
 close();const epoch=detailEpoch,auth=user.token;selectedId.value=id;expectedProject.value=context.projectId||props.projectId||undefined;drawer.value=true;loading.value=true
 try{
  const [row,capabilities]=await Promise.all([context.initial?Promise.resolve(context.initial):api.getMoldApplication(id),props.options?Promise.resolve(props.options):api.getMoldOptions()])
  if(!current(epoch,auth))return
  if(row.applicationId!==id||expectedProject.value&&(row.sourceSnapshot?.research?.projectId||row.productLineId||row.projectId)!==expectedProject.value)throw Error('该申请不属于当前新品，请重新选择')
  detail.value=row;localOptions.value=capabilities
  if(context.reviewHistorical&&row.sourceSystem==='dingtalk'&&capabilities.canConvert)await openHistoricalAssociation()
 }catch(e){if(current(epoch,auth))error.value=e instanceof Error?e.message:'审批详情读取失败，请重试'}finally{if(current(epoch,auth))loading.value=false}
}
function retryOpen(){if(selectedId.value)return open(selectedId.value,{projectId:expectedProject.value})}
async function attempt(action:()=>Promise<unknown>){const auth=user.token,epoch=detailEpoch;try{await action()}catch(e){if(!current(epoch,auth)||e==='cancel'||e==='close')return;error.value=e instanceof Error?e.message:'操作失败，请核对后重试';ElMessage.error(uiText(error.value))}}
function changed(row:api.MoldApplication){detail.value=row;workspace.changed();emit('changed',row)}
async function write(operation:(row:api.MoldApplication)=>Promise<api.MoldApplication>){if(!detail.value||busy.value)return;const row=detail.value,epoch=detailEpoch,auth=user.token;busy.value=true;error.value='';try{const next=await operation(row);if(current(epoch,auth)&&detail.value?.applicationId===row.applicationId)changed(next)}finally{if(current(epoch,auth))busy.value=false}}
function edit(row:api.MoldApplication){close();emit('edit',row)}
function openProject(row:api.MoldApplication){if(props.researchHost&&researchProjectId(row)){close();return}return router.push({path:researchProjectId(row)?'/product-research':'/projects',query:{productId:String(researchProjectId(row)||row.projectId)}})}
async function withdraw(){if(!detail.value||busy.value)return;const row=detail.value,epoch=detailEpoch,auth=user.token;await ElMessageBox.confirm(uiText('撤回钉钉申请，确认成功后复制为新的 PLM 草稿。原流程记录会保留。'),uiText('撤回并修订'),{confirmButtonText:uiText('撤回并复制'),cancelButtonText:uiText('取消')});if(!current(epoch,auth))return;await write(original=>api.withdrawMoldApplication(original.applicationId,original.version));if(current(epoch,auth)&&detail.value&&detail.value.applicationId!==row.applicationId)edit(detail.value)}
async function removeDraft(row:api.MoldApplication){
 if(!row.canDeleteDraft||deletingId.value!==null)return;const auth=user.token,epoch=detailEpoch;deletingId.value=row.applicationId
 try{await ElMessageBox.confirm(uiText('确定删除“{value0}”的开模申请草稿？删除后将从列表移除，手机型号及已有模具资料保留。',{value0:currentPhoneName(row)}),uiText('删除草稿'),{type:'warning',confirmButtonText:uiText('确认删除'),cancelButtonText:uiText('保留草稿'),confirmButtonClass:'el-button--danger'});if(auth!==user.token||epoch!==detailEpoch)return;await api.deleteMoldDraft(row.applicationId,row.version);if(auth!==user.token||epoch!==detailEpoch)return;if(detail.value?.applicationId===row.applicationId)close();workspace.changed();emit('deleted',row.applicationId);ElMessage.success(uiText('草稿已删除'))}
 catch(e){if(auth===user.token&&epoch===detailEpoch&&e!=='cancel'&&e!=='close'){error.value=e instanceof Error?e.message:'删除失败，请刷新后重试';emit('error',error.value);ElMessage.error(uiText(error.value))}}finally{if(auth===user.token)deletingId.value=null}
}
async function syncOne(){if(options.value?.administrator)await write(row=>api.syncMoldApplication(row.applicationId))}
async function archiveFiles(){if(detail.value?.canArchiveFiles)await write(row=>api.archiveMoldFiles(row.applicationId))}
async function retryProvision(){if(options.value?.canConvert&&detail.value?.approvalGranted)await write(row=>api.retryMoldProvision(row.applicationId,row.version))}
async function resolveExecution(action:'resume'|'terminate'){if(!detail.value||!options.value?.canConvert||busy.value)return;const auth=user.token,epoch=detailEpoch;const response=await ElMessageBox.prompt(uiText('请填写工程处理原因，原始审批与已发生进度将保留。'),action==='resume'?uiText('继续开模'):uiText('终止开模'),{inputType:'textarea',inputValidator:value=>!!value?.trim()||uiText('请填写原因')});if(!current(epoch,auth))return;await write(row=>api.resolveMoldExecution(row.applicationId,{version:row.version,action,reason:response.value}))}
const historyOpen=ref(false),historyPreview=ref<api.MoldHistoricalPreview>(),historyBusy=ref(false),historyError=ref(''),historyPhoneIds=ref<number[]>([])
const historySelection=reactive({phoneModelId:null as number|null,productLineId:null as number|null,projectId:null as number|null,itemId:null as number|null,moldSetId:null as number|null,reason:'',confirmPhoneCorrection:false})
let historyEpoch=0
const historyProject=computed(()=>historyPreview.value?.projects.find(p=>p.projectId===Number(historySelection.projectId)))
const historySets=computed(()=>historyPreview.value?.sets.filter(s=>s.itemId===Number(historySelection.itemId))||[])
const historySet=computed(()=>historySets.value.find(s=>s.moldSetId===Number(historySelection.moldSetId)))
const correctingHistoricalPhone=computed(()=>!!detail.value?.phoneModelId&&Number(historySelection.phoneModelId)!==detail.value.phoneModelId)
const historyCanSave=computed(()=>!historyBusy.value&&!!historySelection.phoneModelId&&!!historySelection.productLineId&&!!historySelection.reason.trim()&&(!historySelection.projectId||!!historyProject.value&&!historyProject.value.blockedReason)&&(!historySelection.moldSetId||!!historySelection.itemId&&!!historySet.value&&!historySet.value.blockedReason)&&(!correctingHistoricalPhone.value||historySelection.confirmPhoneCorrection))
async function loadHistoricalPreview(initial=false){
  if(!detail.value)return;const id=detail.value.applicationId,auth=user.token,epoch=++historyEpoch;historyBusy.value=true;historyError.value=''
  try{const value=await api.previewMoldHistoricalAssociation(id,{phoneModelId:historySelection.phoneModelId,productLineId:historySelection.productLineId});if(!drawer.value||auth!==user.token||epoch!==historyEpoch||detail.value?.applicationId!==id)return;historyPreview.value=value;historySelection.productLineId=value.selectedProductLineId;historySelection.phoneModelId=value.standardPhone?.phoneModelId||historySelection.phoneModelId;historyPhoneIds.value=historySelection.phoneModelId?[historySelection.phoneModelId]:[]
    if(initial){historySelection.projectId=value.projects.some(p=>p.projectId===detail.value?.projectId&&!p.blockedReason)?detail.value.projectId:null;historySelection.itemId=value.items.some(i=>i.itemId===detail.value?.itemId)?detail.value.itemId:null;historySelection.moldSetId=value.sets.some(s=>s.moldSetId===detail.value?.moldSetId&&!s.blockedReason)?detail.value.moldSetId:null}
  }catch(e){if(auth===user.token&&epoch===historyEpoch)historyError.value=e instanceof Error?e.message:'历史关联选项读取失败，请重试'}finally{if(auth===user.token&&epoch===historyEpoch)historyBusy.value=false}
}
async function openHistoricalAssociation(){if(!detail.value)return;Object.assign(historySelection,{phoneModelId:detail.value.phoneModelId||null,productLineId:detail.value.productLineId||null,projectId:null,itemId:null,moldSetId:null,reason:'',confirmPhoneCorrection:false});historyPreview.value=undefined;historyOpen.value=true;await loadHistoricalPreview(true)}
function changeHistoricalProduct(){Object.assign(historySelection,{projectId:null,itemId:null,moldSetId:null});void loadHistoricalPreview()}
function chooseHistoricalPhone(phones:CompatiblePhone[]){if(phones.length!==1){historyPhoneIds.value=historySelection.phoneModelId?[historySelection.phoneModelId]:[];ElMessage.warning(uiText('历史关联请选择一款明确的标准手机'));return}historySelection.phoneModelId=phones[0]!.phoneModelId;historySelection.confirmPhoneCorrection=false;Object.assign(historySelection,{projectId:null,itemId:null,moldSetId:null});void loadHistoricalPreview()}
function changeHistoricalProject(){const item=historyProject.value?.linkedItemId;historySelection.itemId=item&&historyPreview.value?.items.some(i=>i.itemId===item)?item:null;historySelection.moldSetId=null}
async function saveHistoricalAssociation(){if(!detail.value||!historyPreview.value||!historyCanSave.value)return;const id=detail.value.applicationId,auth=user.token,epoch=historyEpoch;historyBusy.value=true;historyError.value=''
  try{const row=await api.associateMoldHistory(id,{version:historyPreview.value.application.version,phoneModelId:Number(historySelection.phoneModelId),productLineId:Number(historySelection.productLineId),projectId:historySelection.projectId==null?null:Number(historySelection.projectId),itemId:historySelection.itemId==null?null:Number(historySelection.itemId),moldSetId:historySelection.moldSetId==null?null:Number(historySelection.moldSetId),reason:historySelection.reason.trim(),confirmPhoneCorrection:historySelection.confirmPhoneCorrection});if(!drawer.value||auth!==user.token||epoch!==historyEpoch||detail.value?.applicationId!==id)return;changed(row);historyOpen.value=false;ElMessage.success(uiText('历史关系已关联，适配待确认'))
  }catch(e){if(auth===user.token&&epoch===historyEpoch)historyError.value=e instanceof Error?e.message:'保存失败，请核对原值与权限后重试'}finally{if(auth===user.token&&epoch===historyEpoch)historyBusy.value=false}
}
const targetCorrectionOpen=ref(false),correction=reactive({executionIntent:'new' as 'new'|'new_set',targetItemId:null as number|null,targetProjectId:null as number|null,reason:''}),correctionTargets=ref<api.MoldTargetOptions>({projects:[],items:[]})
async function openTargetCorrection(){if(!detail.value?.phoneModelId||!detail.value.productLineId)return;const row=detail.value,epoch=detailEpoch,auth=user.token;const targets=await api.getMoldTargetOptions(row.phoneModelId!,row.productLineId!);if(!current(epoch,auth))return;correctionTargets.value=targets;Object.assign(correction,{executionIntent:row.executionIntent==='new_set'?'new_set':'new',targetItemId:row.targetItemId||null,targetProjectId:row.targetProjectId||null,reason:''});targetCorrectionOpen.value=true}
async function saveTargetCorrection(){if(!options.value?.canConvert)return;await write(row=>api.correctMoldTargets(row.applicationId,{version:row.version,...correction}));targetCorrectionOpen.value=false}
watch(()=>[props.projectId,user.token],()=>{close();localOptions.value=undefined;selectedId.value=undefined})
onBeforeUnmount(close)
defineExpose({open,close,removeDraft})
</script>
<template>
    <el-drawer class="application-drawer" :style="{'--el-font-size-base':'12px'}" :model-value="drawer" @update:model-value="(value:boolean)=>{if(!value)close()}" :title='uiText("开模申请详情")' size="min(980px,92vw)">
      <div v-loading="loading"><el-alert v-if="error" :title="uiText(error)" type="error" :closable="false"><el-button link @click="retryOpen">{{uiText('重试读取审批详情')}}</el-button></el-alert>
      <template v-if="detail"><h2>{{ currentPhoneName(detail) }} · {{ detail.tipo }}</h2><p>{{ detail.approvalNo||uiText('申请 #{value0}',{value0:(detail.applicationId)}) }} · {{ uiText(label(detail)) }} · {{ detail.originatorName||uiText('PLM草稿') }}</p><el-alert v-if="detail.lastError" :title="detail.lastError" type="warning" :closable="false"/>
        <p v-if="detail.refusal" class="refusal"><strong>{{uiText('已拒绝')}} · {{currentPhoneName(detail)}}</strong> · {{detail.refusal.reason||uiText('审批意见未提供')}}<span v-if="detail.refusal.actorName"> · {{detail.refusal.actorName}}</span></p>
        <div v-if="researchProjectId(detail)&&['rejected','withdrawn','terminated'].includes(detail.businessStatus||detail.status)" class="tools"><span>{{uiText('本型号申请已结束，原审批记录保留')}}</span><el-button v-if="options?.canCreate" link type="primary" @click="emit('other-phone',researchProjectId(detail)!)">{{uiText('选择其他型号')}}</el-button></div>
        <div class="tools"><el-button v-if="detail.canDeleteDraft" type="danger" plain :loading="deletingId===detail.applicationId" :disabled="deletingId!==null" @click="removeDraft(detail)">{{ uiText("删除草稿") }}</el-button><el-button v-if="detail.status==='draft'&&options?.canCreate" @click="edit(detail)">{{ uiText("继续草稿") }}</el-button><el-button v-if="options?.administrator&&detail.instanceId" @click="attempt(syncOne)">{{ uiText("同步此流程") }}</el-button><el-button v-if="options?.canSubmit&&detail.status==='submitted'&&!detail.projectId" @click="attempt(withdraw)">{{ uiText("撤回并修订") }}</el-button><el-button v-if="options?.canConvert&&detail.sourceSystem==='dingtalk'" type="primary" @click="attempt(openHistoricalAssociation)">{{hasHistoricalAssociation(detail)?uiText('更正历史关联'):uiText('核对并关联已有资料')}}</el-button></div>
        <el-alert v-if="detail.historicalAssociation" :title='uiText("历史关系已关联，适配待确认")' type="info" :closable="false"><p>{{detail.historicalAssociation.reason}} · {{detail.historicalAssociation.actorName}} · {{chinaTime(detail.historicalAssociation.associatedAt)}}</p><p>{{ uiText("本次只补已有资料关联；审批原文与刻码保留，不授予执行或共模适配。") }}</p></el-alert>
        <el-alert v-if="detail.provisioningError" :title="detail.provisioningError" type="warning" :closable="false"><el-button v-if="options?.canConvert&&detail.approvalGranted" size="small" @click="attempt(retryProvision)">{{ uiText("重试自动建档") }}</el-button><el-button v-if="options?.canConvert&&detail.approvalGranted&&!researchProjectId(detail)" size="small" @click="attempt(openTargetCorrection)">{{ uiText("核对建档目标") }}</el-button></el-alert>
        <p v-if="detail.authorization">{{ uiText("周汉琴 / Tiffany 已同意 · ") }}{{ chinaTime(detail.authorization.approvedAt) || uiText('同意时间待核对') }}</p>
        <el-alert v-if="detail.executionStatus==='paused'&&!hasHistoricalAssociation(detail)" :title='uiText("后续审批拒绝、撤回或终止，开模已暂停；已发生记录保留")' type="warning" :closable="false"><el-button v-if="options?.canConvert" size="small" @click="attempt(()=>resolveExecution('resume'))">{{ uiText("工程确认继续") }}</el-button><el-button v-if="options?.canConvert" size="small" @click="attempt(()=>resolveExecution('terminate'))">{{ uiText("工程确认终止") }}</el-button></el-alert>
        <p v-if="detail.executionResolution?.action==='resume'||detail.executionResolution?.action==='terminate'">{{ uiText("工程处理：") }}{{ detail.executionResolution.action==='resume'?uiText('继续开模'):uiText('终止开模') }} · {{ detail.executionResolution.reason }} · {{ detail.executionResolution.actorName }}</p>
        <div v-if="detail.projectId||researchProjectId(detail)" class="tools"><el-button @click="openProject(detail)">{{ uiText(researchProjectId(detail)?"打开新品项目":"打开项目") }}</el-button><el-button @click="router.push({path:'/market-watch',query:{itemId:detail.itemId,panel:'market-data'}})">{{ uiText("市场资料维护") }}</el-button><el-button @click="router.push({path:'/molds',query:{moldSetId:detail.moldSetId}})">{{ uiText("模具台账") }}</el-button></div>
        <el-descriptions :column="viewportWidth<760?1:2" border><el-descriptions-item :label="detail.standardPhone?uiText('当前标准手机编码'):uiText('历史手机编码')">{{ currentPhoneCode(detail) }}</el-descriptions-item><el-descriptions-item v-if="detail.standardPhone" :label='uiText("申请原型号")'>{{detail.model||'—'}}</el-descriptions-item><el-descriptions-item v-if="detail.originalPhoneModelCode" :label='uiText("申请原手机编码")'>{{detail.originalPhoneModelCode}}</el-descriptions-item><el-descriptions-item :label='uiText("开模方式")'>{{ detail.executionIntent==='new_set'?uiText('已有主档加开一套'):detail.executionIntent==='reuse'?uiText('历史复用申请'):uiText('新建模具主档') }}</el-descriptions-item><el-descriptions-item :label='uiText("来源系统")'>{{detail.sourceSystem}}</el-descriptions-item><el-descriptions-item :label='uiText("钉钉流程状态")'>{{ statusNames[detail.remoteStatus||'']||detail.remoteStatus||uiText('尚未提交钉钉') }}</el-descriptions-item><el-descriptions-item :label='uiText("审批结果")'>{{ detail.remoteResult==='agree'?uiText('同意'):detail.remoteResult==='refuse'?uiText('拒绝'):detail.remoteResult||'—' }}</el-descriptions-item><el-descriptions-item :label='uiText("申请内部阶段")'>{{ statusNames[detail.status]||detail.status }}</el-descriptions-item><el-descriptions-item v-for="c in controls" :key="c.key" :label="c.label">{{ detail.form[c.key]||'—' }}</el-descriptions-item><el-descriptions-item :label='uiText("生成的编码")'>{{ detail.generatedCodes||'—' }}</el-descriptions-item><el-descriptions-item :label='uiText("信息完成状态")'>{{ detail.form.informationComplete||'—' }}</el-descriptions-item><el-descriptions-item :label='uiText("所在部门")'>{{ detail.departmentName||'—' }}</el-descriptions-item></el-descriptions>
        <el-collapse v-if="detail.sourceSnapshot"><el-collapse-item :title='uiText("市场机型来源快照")' name="sources"><p>{{ uiText("采集快照 ") }}{{ chinaTime(String(detail.sourceSnapshot.capturedAt||'')) }}</p><div v-for="(source,index) in sourceRecords(detail)" :key="index" class="source-record"><span>{{ source.country||source.source_country||uiText('市场待核对') }} · {{ source.source_name||uiText('来源待核对') }} · {{ source.brand }} {{ source.model }}</span><span>{{ source.price_display||source.price_raw||uiText('采集价格未提供') }}</span><a v-if="sourceUrl(source)" :href="sourceUrl(source)" target="_blank" rel="noopener noreferrer">{{ uiText("查看来源") }}</a></div></el-collapse-item></el-collapse>
        <div class="tools"><h3>{{ uiText("图片与附件") }}</h3><el-button v-if="detail.canArchiveFiles&&detail.files?.some(f=>f.downloadStatus!=='downloaded'&&f.downloadStatus!=='pending_upload')" :disabled="busy" @click="attempt(archiveFiles)">{{detail.files.some(f=>f.downloadStatus==='download_failed')?uiText('重试归档原附件'):uiText('归档原审批附件')}}</el-button></div><div class="photo-grid"><MoldApplicationFile v-for="f in detail.files" :key="`${detail.applicationId}:${f.attachmentId}`" :application-id="detail.applicationId" :file="f" :active="drawer" compact/></div>
        <h3>{{ uiText("审批时间线") }}</h3><el-timeline><el-timeline-item v-for="activity in detail.activities?.filter(a=>a.type!=='task')" :key="activity.activityId" :timestamp="chinaTime(activity.occurredAt)"><span>{{ activity.payload.operation_type==='START_PROCESS_INSTANCE'?uiText('发起审批'):activity.payload.operation_type==='EXECUTE_TASK_NORMAL'?uiText('处理审批'):activity.payload.operation_type==='TERMINATE_PROCESS_INSTANCE'?uiText('终止流程'):activity.type }}</span><el-tag size="small" v-if="activity.payload.operation_result&&activity.payload.operation_result!=='NONE'">{{ activity.payload.operation_result==='AGREE'?uiText('同意'):activity.payload.operation_result }}</el-tag><p>{{ uiText(moldHandlerName({name:activity.actorName,userId:activity.actorId,taskId:activity.taskId})) }} {{ activity.payload.remark }}</p></el-timeline-item></el-timeline>
        <h3>{{ uiText("当前任务") }}</h3><template v-if="detail.currentHandlers!==undefined"><p v-for="(handler,index) in detail.currentHandlers" :key="handler.taskId||index" class="handler-evidence">{{moldHandlerName(handler)}}{{ uiText(" · 原账号 ") }}{{handler.userId||uiText('未提供')}}{{ uiText(" · 任务 ") }}{{handler.taskId||uiText('待核对')}}</p></template><template v-else-if="detail.remoteStatus==='RUNNING'&&!detail.terminal&&!['rejected','withdrawn','terminated'].includes(detail.businessStatus||detail.status)"><p v-for="task in detail.activities?.filter(a=>a.type==='task'&&a.payload.task_status==='RUNNING')" :key="task.activityId">{{ uiText("处理人 ") }}{{ uiText(moldHandlerName({name:task.actorName,userId:task.actorId,taskId:task.taskId})) }}{{ uiText(" · 任务 ") }}{{ task.taskId }}</p></template>
      </template></div>
    </el-drawer>
    <el-dialog v-model="targetCorrectionOpen" :title='uiText("核对自动建档目标")' width="min(620px,94vw)"><el-form label-position="top"><el-form-item :label='uiText("开模方式")'><el-radio-group v-model="correction.executionIntent"><el-radio value="new">{{ uiText("新建模具主档") }}</el-radio><el-radio value="new_set">{{ uiText("已有主档加开一套") }}</el-radio></el-radio-group></el-form-item><el-form-item v-if="correction.executionIntent==='new_set'" :label='uiText("已有模具主档")'><el-select v-model="correction.targetItemId" filterable><el-option v-for="item in correctionTargets.items" :key="item.itemId" :value="item.itemId" :label="`${item.moldName} · ${item.compatibleModels}`"/></el-select></el-form-item><el-form-item :label='uiText("型号项目")'><el-select v-model="correction.targetProjectId" clearable :placeholder='uiText("无匹配项目则新建")'><el-option v-for="project in correctionTargets.projects" :key="project.projectId" :value="project.projectId" :label="project.productName"/></el-select></el-form-item><el-form-item :label='uiText("工程核对原因")'><el-input v-model="correction.reason" type="textarea" :rows="3"/></el-form-item></el-form><template #footer><el-button type="primary" :disabled="!correction.reason.trim()" @click="attempt(saveTargetCorrection)">{{ uiText("保存目标并重试") }}</el-button></template></el-dialog>
    <el-dialog v-model="historyOpen" :title='uiText("核对并关联已有资料")' width="min(900px,94vw)" :style="{'--el-font-size-base':'12px'}" :close-on-click-modal="false" class="history-association-dialog">
      <el-alert :title='uiText("仅关联已存在的项目、主档和实物套；不新建任何实物，也不确认适配。")' type="info" :closable="false"/>
      <p v-if="detail">{{ uiText("申请原文：") }}{{detail.model||uiText('未填写')}} · {{detail.tipo||uiText('未填写')}}{{ uiText(" · 原刻码 ") }}{{detail.generatedCodes||uiText('原编码缺失，仍可核对已有关系')}}</p>
      <el-alert v-if="historyError" :title="historyError" type="error" :closable="false"><el-button size="small" @click="loadHistoricalPreview()">{{ uiText("重新读取选项") }}</el-button></el-alert>
      <el-form label-position="top" v-loading="historyBusy"><el-form-item :label='uiText("当前标准手机")'><SharedCompatiblePhoneSelector v-model="historyPhoneIds" :multiple="false" @selected="chooseHistoricalPhone"/></el-form-item>
        <el-checkbox v-if="correctingHistoricalPhone" v-model="historySelection.confirmPhoneCorrection" :aria-label='uiText("明确更正历史手机关联")'>{{ uiText("明确更正原标准手机关联，原文保留并记录本次原因") }}</el-checkbox>
        <el-form-item :label='uiText("实际产品线")'><el-select v-model="historySelection.productLineId" :aria-label='uiText("历史关联产品线")' @change="changeHistoricalProduct"><el-option v-for="line in historyPreview?.productLines||options?.productLines" :key="line.productId" :value="line.productId" :label="line.productName"/></el-select></el-form-item>
        <el-form-item :label='uiText("已存在的型号项目")'><el-select v-model="historySelection.projectId" filterable clearable :aria-label='uiText("历史关联已有项目")' @change="changeHistoricalProject"><el-option v-for="project in historyPreview?.projects" :key="project.projectId" :value="project.projectId" :disabled="!!project.blockedReason" :label="`${project.productName}${project.blockedReason?' · '+project.blockedReason:''}`"/></el-select><small v-if="!historyBusy&&(!historySelection.phoneModelId||!historySelection.productLineId)">{{ uiText("请选择当前标准手机和实际产品线；项目、主档、具体套可分层补齐。") }}</small><small v-else-if="!historyBusy&&!historyError&&historyPreview&&!historyPreview.projects.length">{{ uiText("此产品线暂无获授权的已有项目；可以先保存其他明确关系，或使用集中补链登记已核实项目。") }}</small></el-form-item>
        <el-form-item :label='uiText("已存在的模具主档")'><el-select v-model="historySelection.itemId" filterable clearable :aria-label='uiText("历史关联模具主档")' @change="historySelection.moldSetId=null"><el-option v-for="item in historyPreview?.items" :key="item.itemId" :value="item.itemId" :disabled="!!historyProject?.linkedItemId&&historyProject.linkedItemId!==item.itemId" :label="uiText('{value0} · 原刻码 {value1}',{value0:(item.moldName),value1:(item.engravedCode||'待核对')})"/></el-select></el-form-item>
        <el-form-item :label='uiText("该主档已存在的实物套")'><el-select v-model="historySelection.moldSetId" filterable clearable :aria-label='uiText("历史关联实物套")'><el-option v-for="set in historySets" :key="set.moldSetId" :value="set.moldSetId" :disabled="!!set.blockedReason" :label="uiText('第 {value0} 套 · {value1} · PC {value2} / TPU {value3}{value4}',{value0:(set.setNo),value1:(set.setName),value2:(set.pcCode||'原码待核对'),value3:(set.tpuCode||'原码待核对'),value4:(set.blockedReason?' · '+set.blockedReason:'')})"/></el-select><small v-if="historySelection.itemId&&!historySets.length">{{ uiText("该主档暂无获授权的已有实物套；不会根据原编码自动补造。") }}</small></el-form-item>
        <p v-for="set in historySets.filter(s=>s.blockedReason)" :key="set.moldSetId">{{ uiText("第 ") }}{{set.setNo}}{{ uiText(" 套：") }}{{set.blockedReason}} <el-button size="small" link @click="router.push({path:'/molds',query:{moldSetId:set.moldSetId}})">{{ uiText("核对该套实物") }}</el-button></p>
        <el-form-item :label='uiText("核对依据／更正原因")' required><el-input v-model="historySelection.reason" type="textarea" :rows="3" :maxlength="4000" :aria-label='uiText("历史关联核对原因")' :placeholder='uiText("说明原申请与所选现有资料的关系及核对依据")'/></el-form-item>
      </el-form><template #footer><el-button @click="historyOpen=false">{{ uiText("取消") }}</el-button><el-button type="primary" :disabled="!historyCanSave" :loading="historyBusy" @click="saveHistoricalAssociation">{{ uiText("保存已有资料关联") }}</el-button></template>
    </el-dialog>
</template>
<style scoped>
.tools{display:flex;gap:6px;align-items:center;flex-wrap:wrap;margin:10px 0}.tools .el-button+.el-button{margin-left:0}.source-record{display:flex;flex-wrap:wrap;gap:4px 12px;padding:4px 0;overflow-wrap:anywhere}.photo-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,180px),1fr));gap:8px}.el-descriptions{margin-top:12px}.el-descriptions :deep(.el-descriptions__table){table-layout:fixed}.el-descriptions :deep(.el-descriptions__cell){overflow-wrap:anywhere}.refusal{color:var(--el-color-danger);overflow-wrap:anywhere}h3{margin:18px 0 10px;font-size:13px}
</style>
